  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Doxazosin, a high-transfer analogue, has an absolute oral bioavailability of 65 ± 14% in young subjects compared with intravenous administration, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ofloxacin, despite polar and ionizable groups, shows >95% oral bioavailability in healthy subjects, demonstrating that low logD/high TPSA does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "ACT-1004-1239 has an absolute bioavailability of 53% in healthy subjects across a 1–200 mg dose range, providing a direct quantitative F measurement above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Suvorexant has a mean oral bioavailability of 82% in humans, another high-F example with a heterocyclic, fluorinated structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Dovitinib has around 75% oral bioavailability in humans, supporting high F despite extensive hepatic metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Balcinrenone has an absolute bioavailability of 52% in a human mass balance study, directly meeting the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Mirtazapine has about 50% absolute bioavailability in humans, showing that basic amine-containing molecules can have adequate oral F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values well above 20% (50–100%), with no low-F evidence. The query's low logD and high TPSA raise a permeability concern, but the analogous data show such physicochemical features do not preclude F ≥ 20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No human PK or metabolic stability data for the query.",
    "No data on transporter-mediated absorption or efflux for the query.",
    "The physicochemical prior suggests low passive permeability, but its impact on F is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

